WITH cleaned AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, ROUND(DATEDIFF(delivered_date, shipped_date) / 30, 1) months_shipped_date_to_delivered_date, COALESCE(carrier, 'OTHER') carrier_filled FROM shipments WHERE shipped_date >= '2025-06-29' AND shipped_date > DATE '2023-03-19') SELECT id, carrier, cost, months_shipped_date_to_delivered_date, carrier_filled, LEAD(months_shipped_date_to_delivered_date, 2) OVER (PARTITION BY order_id ORDER BY cost, id) next_months_shipped_date_to_delivered_date, LEAD(months_shipped_date_to_delivered_date, 1, 0) OVER (PARTITION BY order_id ORDER BY shipped_date, id) next_months_shipped_date_to_delivered_date_2, AVG(cost) OVER (PARTITION BY carrier ORDER BY cost, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) cost_avg_6_prior, PERCENT_RANK() OVER (PARTITION BY order_id, carrier ORDER BY months_shipped_date_to_delivered_date) months_shipped_date_to_delivered_date_percent_rank FROM cleaned
